import{_ as i,o as e,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Jewel -- Scrub Repair","description":"","frontmatter":{"title":"CDS Jewel -- Scrub Repair","date":"2015-08-04T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","数据修复","一致性检查","Scrub","Repair"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_Scrub_Repair.md","filePath":"posts/2015/CDS_Jewel_--_Scrub_Repair.md","lastUpdated":1780459816000}'),a={name:"posts/2015/CDS_Jewel_--_Scrub_Repair.md"};function o(s,l,p,u,n,_){return e(),r("div",null,[...l[0]||(l[0]=[t('<p>在&quot;CDS Jewel -- Scrub Repair&quot;会议纪要中，讨论了Ceph分布式存储系统中数据修复和一致性检查的优化问题。以下是会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划：</p><h3 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h3><ul><li>会议重点讨论了Ceph系统中数据修复（scrub）和一致性检查（repair）的优化问题。</li><li>目前的修复过程效率低下，且存在错误猜测等问题。</li><li>需要提升OSD（对象存储守护进程）的智能程度，以更精确地识别和修复不一致的对象。</li></ul><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题： <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题：&quot;">​</a></h3><ol><li><p><strong>修复流程重构</strong>：</p><ul><li>重构修复流程，使其能够对单个对象进行修复操作。</li><li>优化scrub操作，使其在修复模式下能够对单个对象执行修复。</li></ul></li><li><p><strong>不一致对象查询</strong>：</p><ul><li>允许客户端查询不一致的PG（存储池）。</li><li>在librettos中实现查询不一致PG的方法。</li></ul></li><li><p><strong>不一致对象信息获取</strong>：</p><ul><li>获取PG中不一致对象的信息，并确保信息可持久化。</li><li>考虑将信息存储为临时对象或隐藏元数据对象。</li></ul></li><li><p><strong>智能修复</strong>：</p><ul><li>允许通过预准备的现有对象进行有针对性的修复。</li><li>使用JSON格式存储不一致信息，以实现向后兼容性。</li></ul></li></ol><h3 id="决定的事项" tabindex="-1">决定的事项： <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项：&quot;">​</a></h3><ol><li><p><strong>修复流程优化</strong>：</p><ul><li>优化修复流程，使其能够对单个对象进行修复。</li><li>重新设计scrub操作，使其能够执行单个对象的修复操作。</li></ul></li><li><p><strong>不一致对象查询与信息获取</strong>：</p><ul><li>在librettos中实现查询不一致PG的方法。</li><li>获取PG中不一致对象的信息，并确保信息可持久化。</li></ul></li><li><p><strong>智能修复</strong>：</p><ul><li>允许通过预准备的现有对象进行有针对性的修复。</li><li>使用JSON格式存储不一致信息。</li></ul></li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ol><li><p><strong>开发与测试</strong>：</p><ul><li>开发并测试修复流程优化方案。</li><li>开发并测试不一致对象查询与信息获取功能。</li><li>开发并测试智能修复功能。</li></ul></li><li><p><strong>文档与培训</strong>：</p><ul><li>编写相关文档，介绍修复流程优化方案。</li><li>对相关人员进行培训，确保他们了解新功能的使用方法。</li></ul></li><li><p><strong>反馈与迭代</strong>：</p><ul><li>收集用户反馈，并根据反馈进行迭代优化。</li></ul></li></ol>',9)])])}const h=i(a,[["render",o]]);export{d as __pageData,h as default};
